// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address from, uint256 v, uint256 count) public {
        vm.assume(from != address(0));
        count = bound(count, 1, 5);
        Token token = new Token();
        address[] memory tos = new address[](count);
        for (uint256 i = 0; i < count; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encode(i, from, v)))));
            vm.assume(tos[i] != address(0));
        }
        bool ok = c.transfer(from, address(token), tos, v);
        assertTrue(ok);
    }
}

contract Token {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
